arguments.new_string:
if tz is not None:
    tz = groups[tz]
if tz == 'Z':
    tz = FixedTzOffset(0, 'UTC')
elif tz:
    tz = tz.strip()
    if tz.isupper():
        # TODO use the awesome python TZ module?
        pass
    else:
        sign = tz[0]
        if ':' in tz:
            tzh, tzm = tz[1:].split(':')
        elif len(tz) == 4:  # 'snnn'
            tzh, tzm = tz[1], tz[2:4]
        else:
            tzh, tzm = tz[1:3], tz[3:5]
        offset = int(tzm) + int(tzh) * 60
        if sign == '-':
            offset = -offset
        # Normalize the timezone name to HH:MM format for consistency
        tzname = '%s%02d:%02d' % (sign, int(tzh), int(tzm))
        tz = FixedTzOffset(offset, tzname)

